import {escapeHtml as esc} from './message-format.js';
const kind=v=>typeof v==='string'?v:Object.keys(v||{})[0];
const milliseconds=v=>typeof v==='bigint'?Number(v/1000000n):Number(v);
const when=v=>new Date(milliseconds(v)).toLocaleString();
const labels={operational:'Operational',unknown:'Status unconfirmed',outage:'Service disruption',degraded:'Degraded performance',maintenance:'Maintenance'};
export function renderServiceStatus(page) {
 const states=page.services.map(s=>s.state),overall=states.includes('outage')?'outage':states.includes('degraded')?'degraded':states.includes('maintenance')?'maintenance':states.includes('unknown')?'unknown':'operational';
 const notices=page.notices,upcoming=notices.filter(n=>kind(n.phase)==='scheduled'&&milliseconds(n.startsAt)>Date.now()),active=notices.filter(n=>kind(n.phase)!=='resolved'&&!upcoming.includes(n)),past=notices.filter(n=>kind(n.phase)==='resolved');
 const cards=items=>items.map(n=>`<article class="ss-notice"><div class="ss-notice-head"><span class="ss-phase">${esc(kind(n.phase))}</span><span>${n.services.map(esc).join(' · ')}</span></div><h3>${esc(n.title)}</h3>${milliseconds(n.startsAt)>0?`<p class="kv">Maintenance window: ${esc(when(n.startsAt))} – ${esc(when(n.endsAt))}${milliseconds(n.endsAt)<Date.now()&&kind(n.phase)!=='resolved'?' · awaiting completion confirmation':''}</p>`:''}<ol class="ss-timeline">${[...n.updates].reverse().map(u=>`<li><p>${esc(u.message)}</p><small>${esc(kind(u.phase))} · ${esc(when(u.at))}</small></li>`).join('')}</ol></article>`).join('');
 return `<div class="ss-page"><header class="ss-header"><span class="eyebrow">SERVICE STATUS</span><h1>${esc(page.title)}</h1><p>${esc(page.description)}</p></header><section class="ss-overall ss-${overall}" role="status"><span class="ss-dot" aria-hidden="true"></span><div><strong>${labels[overall]}</strong><small>Last retrieved ${esc(when(page.checkedAt))}</small></div></section><div class="ss-services">${page.services.map(s=>`<div><strong>${esc(s.name)}</strong><span class="ss-state ss-${s.state}">${esc(labels[s.state]||labels.unknown)}</span>${milliseconds(s.checkedAt)>0?`<small>Confirmed ${esc(when(s.checkedAt))} · valid until ${esc(when(s.validUntil))}</small>`:'<small>No current operational confirmation</small>'}</div>`).join('')}</div>${active.length?`<section class="ss-active"><h2>Current notices</h2>${cards(active)}</section>`:'<p class="ss-quiet">No active notices published.</p>'}${upcoming.length?`<section class="ss-active"><h2>Upcoming maintenance</h2>${cards(upcoming)}</section>`:''}${past.length?`<details class="ss-history"><summary>Resolved incidents · ${past.length}</summary>${cards(past)}</details>`:''}<p class="ss-footnote">Published updates from the response team. Operational confirmations expire; this page does not measure uptime.</p></div>`;
}
export function createWorkspaceStatus({root,api,session,getMe}) {
 let generation=0,timer;const clear=()=>{generation++;clearTimeout(timer);root.replaceChildren();};
 async function show(){clear();const stamp=generation,identity=getMe()?.id;root.innerHTML='<p role="status">Checking service status…</p>';try{const pages=await api().workspaceServiceStatus(session.load());if(stamp!==generation||getMe()?.id!==identity)return;root.innerHTML=pages.length?pages.map(renderServiceStatus).join(''):'<div class="page-heading"><div><h2>Service status</h2><p>No status pages are available for this workspace.</p></div></div>';timer=setTimeout(show,60000);}catch(e){if(stamp===generation){root.innerHTML='<h2>Status unavailable</h2><p>Could not retrieve a fresh status. Try again shortly.</p><button data-status-retry>Try again</button>';root.querySelector('button').onclick=show;}}}
 return{show,clear};
}
